USE={
'période':'Une « période » est un intervalle construit pour l’analyse. Ses limites peuvent être utiles sans correspondre à une rupture nette vécue au même moment par tous les acteurs.',
'document':'Un « document » est une trace produite dans un contexte particulier. Sa conservation donne accès à une source sans garantir qu’elle soit complète, neutre ou représentative.',
'discussion':'Une « discussion » historique peut désigner un échange entre acteurs ou un débat ultérieur entre interprètes. Il faut préciser lequel des deux niveaux fournit la preuve invoquée.',
'frontière':'Une « frontière » peut être politique, administrative ou analytique. Sa présence sur une carte ou dans un règlement n’indique pas automatiquement la même importance dans les pratiques quotidiennes.',
'témoigner':'« Témoigner » signifie rapporter ou manifester quelque chose à partir d’une position située. Un témoignage peut être précieux tout en restant soumis aux limites de mémoire, d’accès et d’intérêt.',
'rumeur':'Une « rumeur » est une information qui circule sans validation suffisante. Elle peut être historiquement importante comme cause de comportement même lorsque son contenu factuel est faux.',
'version':'Une « version » est une forme particulière d’un récit ou d’un compte rendu. Plusieurs versions peuvent partager des faits tout en divergeant sur la sélection, l’ordre et la causalité.',
'événement':'Un « événement » est un fait ou ensemble de faits délimité pour l’analyse. Le nommer ne suffit pas à établir sa cause ni son importance relative dans une séquence plus longue.',
'possibilité':'Une « possibilité » est une alternative compatible avec une partie des données. L’historien la distingue d’une conclusion soutenue en demandant quels indices supplémentaires la rendraient plus ou moins probable.',
'échec':'Un « échec » désigne ici l’absence d’un résultat recherché. Le terme doit préciser le but de quel acteur, faute de quoi un même changement peut être appelé échec par l’un et réussite par l’autre.',
'peinture':'Une « peinture » peut servir de source visuelle, mais elle est aussi une composition. Sa valeur documentaire dépend du genre, du commanditaire, de la convention et du but de l’image.',
'empreinte':'Une « empreinte » est une marque laissée par un contact ou une action. Elle peut attester une présence ou un procédé sans expliquer seule l’intention ni la chronologie complète.',
'copie':'Une « copie » reproduit un autre objet ou texte avec un degré variable de fidélité. Une copie tardive peut préserver un contenu perdu tout en introduisant des erreurs ou des choix nouveaux.',
'indice':'Un « indice » est un élément qui oriente une hypothèse sans constituer toujours une preuve décisive. Sa force dépend des explications rivales capables de produire le même signe.',
'propriété':'Une « propriété » est ici une caractéristique d’un objet ou d’un matériau. L’analyse évite de confondre cette propriété observée avec une provenance ou une fonction qui demandent des arguments supplémentaires.',
'choc':'Un « choc » désigne une perturbation brusque. Le qualifier de cause historique exige de montrer le mécanisme reliant la perturbation aux changements observés plutôt que de s’appuyer sur la seule proximité chronologique.',
'pari':'Un « pari » est une décision prise sous incertitude en acceptant un risque. Dans une source, le terme aide à reconstruire ce qu’un acteur pouvait raisonnablement anticiper sans lui attribuer la connaissance du résultat futur.',
'humeur':'L’« humeur » collective est une catégorie dangereuse si elle transforme quelques déclarations en état mental uniforme. Le terme n’est utile que si les sources, les groupes et les variations sont précisés.',
'réputation':'Une « réputation » est une évaluation sociale qui circule entre acteurs. Elle peut influencer une décision sans correspondre exactement aux compétences ou aux actes de la personne concernée.',
'réellement':'« Réellement » marque une revendication sur ce qui s’est effectivement produit. En source critique, cette force doit être soutenue par des éléments indépendants plutôt que par l’assurance du narrateur.',
'approche':'Une « approche » est une manière organisée de sélectionner des questions, sources et critères. Deux approches peuvent être compatibles sur les faits et diverger sur l’importance attribuée aux mécanismes.',
'commun':'Un facteur « commun » apparaît dans plusieurs cas. Sa répétition peut justifier une comparaison, sans prouver qu’il produit partout le même effet ni qu’il est la cause principale.',
'précédemment':'« Précédemment » situe un élément avant un autre. L’ordre temporel est nécessaire à certaines causalités mais n’est pas, à lui seul, une preuve que l’élément antérieur a causé le suivant.',
'signaler':'« Signaler » signifie attirer l’attention sur un fait ou un écart. Une source peut signaler une anomalie importante sans expliquer pourquoi elle existe ni quelle interprétation est correcte.',
'suivant':'« Suivant » ordonne un élément après un autre dans une séquence. Le terme aide à reconstruire une chronologie tout en rappelant que succession et dépendance causale sont deux relations distinctes.'
}

EXTRA=[
"L’analyse ajoute un test de provenance. Pour chaque pièce, le lecteur note qui l’a produite, pour quel destinataire, à quel moment, avec quel accès aux faits et sous quelles contraintes. Une information répétée dans trois documents qui copient la même source ne compte pas comme trois confirmations indépendantes.",
"Un deuxième test distingue silence et absence. Si une archive ne mentionne pas un événement, cela peut signifier qu’il n’a pas eu lieu, qu’il n’était pas pertinent pour le producteur, qu’il a été omis, ou que la pièce correspondante n’a pas été conservée. La conclusion doit donc annoncer ce que l’absence documentaire permet réellement d’inférer.",
"Le passage compare ensuite causes nécessaires, suffisantes et contributives. Un facteur peut rendre un résultat plus probable sans l’imposer, ou n’agir qu’en combinaison avec une autre condition. Cette distinction empêche de transformer une cause parmi plusieurs en explication totale simplement parce qu’elle est visible dans le dossier.",
"Une quatrième étape contrôle la connaissance rétrospective. Une décision qui paraît irrationnelle après le résultat peut avoir été raisonnable avec l’information disponible avant celui-ci. Le lecteur reconstruit donc l’ensemble d’options plausibles au moment de l’action au lieu d’utiliser l’issue future comme preuve des intentions initiales.",
"La synthèse conserve les désaccords qui ne peuvent pas être tranchés. Elle peut conclure qu’une chronologie est bien établie, qu’un mécanisme est probable et qu’une intention particulière reste incertaine. La précision consiste alors à distribuer des degrés de confiance plutôt qu’à choisir artificiellement une histoire unique.",
"Enfin, le lecteur vérifie la portée comparative. Deux cas qui partagent un vocabulaire institutionnel ou un résultat visible peuvent différer par leurs contraintes, leur échelle et leurs sources. La comparaison est utile lorsqu’elle identifie exactement la dimension commune et les différences susceptibles de modifier le mécanisme."
]

def h(p): return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def fit(ps,lo,hi):
 p=list(ps); t='\n\n'.join(p); i=0
 while len(t.split())<lo and i<len(EXTRA): p[-1]+=' '+EXTRA[i]; i+=1; t='\n\n'.join(p)
 if not lo<=len(t.split())<=hi: raise AssertionError(f'C2 Unit08 word band {len(t.split())} not {lo}-{hi}')
 return p,t

def bridge(fs): return 'Révision interprétative : '+', '.join(f'« {x} »' for x in fs)+'. Ces formes de l’unité précédente sont reprises pour transférer les méthodes de traduction, de contexte et de portée vers la critique historique.'
def qitems(s,forms):
 core=[('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('ambiguity_resolution',s['qamb'],s['aamb'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('rhetorical_function',s['qrhet'],s['arhet'],[forms[3]]),('stance',s['qstance'],s['astance'],[forms[4]])]
 return core+[('vocabulary_in_context',f'Quel rôle historiographique joue « {f} » dans le passage ?',USE[f],[f]) for f in forms]
def make(s,forms,reviews,prior,D,lo,hi,theme):
 ps=list(s['paras']); ps[1]+=' '+' '.join(USE[f] for f in forms); ps[2]+=' '+bridge(reviews); ps,text=fit(ps,lo,hi)
 P=base.prior(prior); new=[c2base.nt(f,text,D) for f in forms]; rev=[base.rev(f,P) for f in reviews]; ids={t['form']:t['id'] for t in new+rev}; q,a=base.qa(qitems(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C2','unit':8,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':['educational','public','professional'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'integrate temporal ordering, evidential qualification, causal modality and retrospective counterfactuals'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'compare provenance, chronology, rival causes, source dependence and calibrated historical synthesis'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C2 Unit08 historical reasoning with fictional archival cases.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Historical cases and archives are fictional; no disputed real-world claim is asserted as fact.']},'paired_text_group':None,'prerequisites':['French C2 Unit07'],'difficulty_notes_internal':'C2 historiography, source criticism, causal explanation and synthesis under uncertainty.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_c2_u08']}

def specs(): return [
{'id':'fr-c2-u08-p01','seq':43,'ptype':'instructional','genre':'source critique','topics':['provenance','periodization','source dependence'],'title':'Une archive abondante peut répéter une seule voix','paras':["Un dépôt fictif conserve des dossiers sur l’ouverture d’un passage commercial entre deux régions imaginaires. Un rapport administratif, trois lettres publiées et un résumé ultérieur décrivent une hausse des déplacements après la nouvelle règle. À première vue, cinq sources semblent confirmer le même récit. Une vérification révèle pourtant que les lettres citent le rapport et que le résumé reprend les lettres. Le dossier sert à distinguer nombre de pièces et indépendance de l’information.","La critique commence par établir la chronologie de production et la relation entre les pièces. Elle demande aussi pourquoi chacune existe, à qui elle s’adresse et ce qu’elle pouvait observer directement.","Le problème devient plus difficile lorsqu’un chercheur découpe les années en avant et après l’ouverture. Ce découpage facilite la comparaison, mais certaines pratiques changent plus tôt et d’autres plus tard. La limite analytique ne doit donc pas être confondue avec une transformation instantanée. Les outils de l’unité précédente rappellent qu’une catégorie utile ne doit pas devenir une essence du contexte étudié.","Une objection affirme que les documents restent utiles même s’ils dépendent les uns des autres. C’est exact : une chaîne de copies peut montrer comment une interprétation s’est diffusée. Mais elle ne fournit pas cinq observations indépendantes du phénomène initial. La question de preuve change selon qu’on étudie le passage commercial lui-même ou la circulation du récit à son sujet.","La conclusion propose une carte de provenance. Chaque affirmation est reliée à la pièce qui la soutient, puis aux sources dont cette pièce dépend. La force d’une conclusion augmente lorsque des traces indépendantes convergent, tandis qu’une répétition dépendante devient elle-même un objet historique à expliquer."],'qclaim':'Pourquoi cinq pièces ne constituent-elles pas nécessairement cinq confirmations indépendantes ?','aclaim':'Parce que plusieurs pièces peuvent reprendre la même source initiale; leur nombre mesure alors la circulation d’un récit plus que l’indépendance des observations.','qamb':'Quelle différence le passage établit-il entre une frontière analytique de période et une rupture historique ?','aamb':'La première est un outil de comparaison choisi par le chercheur; la seconde serait un changement effectif dont le moment doit être établi par les sources.','qassume':'Pourquoi faut-il connaître le destinataire et le but d’un document ?','aassume':'Parce qu’ils influencent ce que l’auteur pouvait vouloir consigner, omettre, simplifier ou défendre.','qrhet':'Quel rôle joue la carte de provenance ?','arhet':'Elle rend visibles les dépendances entre sources et empêche de compter plusieurs reprises comme observations indépendantes.','qstance':'Quelle position le passage adopte-t-il sur les sources dépendantes ?','astance':'Elles restent utiles, notamment pour étudier la circulation d’un récit, mais leur dépendance doit être intégrée à l’évaluation probatoire.'},
{'id':'fr-c2-u08-p02','seq':44,'ptype':'reinforcement','genre':'historiographical comparison','topics':['competing accounts','rumor','chronology and causation'],'title':'Deux récits peuvent partager les dates et contester les causes','paras':["Deux historiens fictifs étudient l’échec d’une expédition commerciale imaginaire. Ils s’accordent sur la chronologie : départ tardif, fermeture temporaire d’un port, retour anticipé. Le premier explique surtout l’issue par une décision de direction; le second insiste sur une rumeur de fermeture durable qui aurait changé le comportement des partenaires avant toute annonce officielle. Le désaccord porte donc moins sur les dates que sur le mécanisme causal.","La comparaison reconstruit chaque chaîne : information disponible, décision intermédiaire, comportement observé, résultat. Elle distingue ce qui est attesté de ce qui demeure hypothétique.","Une rumeur peut avoir des effets même si son contenu est faux. Inversement, sa simple existence ne prouve pas que les acteurs y ont cru ni qu’elle a déterminé leur décision. Une possibilité explicative doit donc produire des prédictions : quels courriers, délais ou changements devraient apparaître si ce mécanisme a réellement compté ? La révision de l’unité précédente sert à conserver plusieurs lectures tant que les indices ne permettent pas de trancher.","Le premier historien répond qu’un ordre interne précède clairement le retour. Le second note que la chronologie est compatible avec les deux mécanismes : la direction peut avoir réagi à la même information circulante. Une cause n’est donc pas identifiée simplement parce qu’elle vient avant l’effet. Il faut établir la relation intermédiaire.","La synthèse finale attribue des degrés de confiance. Le calendrier est élevé, la modification des comportements est moyenne, l’intention exacte de la direction reste faible. Plutôt que de choisir un récit complet par préférence, le dossier sépare les éléments robustes des maillons encore contestés."],'qclaim':'Sur quoi porte principalement le désaccord entre les deux historiens ?','aclaim':'Sur le mécanisme causal reliant l’information, les décisions et l’échec, alors que la chronologie générale est largement partagée.','qamb':'Pourquoi une rumeur fausse peut-elle rester historiquement causale ?','aamb':'Parce que des acteurs peuvent modifier leur comportement en réponse à ce qu’ils croient, même si le contenu de l’information est inexact.','qassume':'Que doit prédire une possibilité causale pour devenir testable ?','aassume':'Des traces ou changements intermédiaires qui devraient apparaître si le mécanisme proposé a réellement influencé les acteurs.','qrhet':'Pourquoi le texte attribue-t-il des degrés de confiance séparés ?','arhet':'Pour éviter qu’une partie bien établie de la chronologie donne artificiellement la même certitude aux intentions ou mécanismes moins documentés.','qstance':'Quelle méthode de comparaison est privilégiée ?','astance':'Comparer les chaînes causales maillon par maillon et conserver l’incertitude lorsque plusieurs versions restent compatibles avec les preuves.'},
{'id':'fr-c2-u08-p03','seq':45,'ptype':'interleaved','genre':'source critique','topics':['material evidence','visual sources','copying'],'title':'Un objet ancien ne raconte pas seul comment il a été utilisé','paras':["Un musée fictif possède une petite boîte peinte, deux dessins anciens qui lui ressemblent et une copie réalisée beaucoup plus tard. Une étiquette affirme que la boîte servait à conserver des messages lors d’une cérémonie. Le dossier demande quelles parties de cette phrase viennent directement de l’objet, lesquelles viennent des représentations et lesquelles sont des inférences modernes.","L’étude matérielle établit d’abord dimensions, pigments, traces d’usure et réparations. L’image peinte fournit aussi des conventions visuelles qui ne doivent pas être lues comme une photographie automatique du quotidien.","Une marque à l’intérieur pourrait provenir d’un objet plié, mais plusieurs usages produiraient une trace comparable. La copie tardive montre comment la boîte a été comprise à une époque suivante; elle n’est pas une fenêtre transparente sur la première utilisation. La révision de l’unité précédente rappelle qu’une origine ou une continuité déclarée doit être séparée des transformations observables.","Un dessin semble représenter la boîte près d’un groupe de personnes. Pourtant, la scène peut être symbolique ou composite. Le lecteur construit donc au moins deux hypothèses de fonction et demande quel nouvel élément — résidu, texte associé, série d’objets comparables — distinguerait mieux les possibilités.","La conclusion hiérarchise les affirmations. Certaines propriétés matérielles sont directement observables; la datation et la relation entre les objets demandent des méthodes supplémentaires; la fonction cérémonielle reste une interprétation tant que les sources indépendantes ne convergent pas. Le but n’est pas de rendre l’objet muet, mais de faire correspondre la force de chaque phrase à la force de son indice."],'qclaim':'Pourquoi la fonction cérémonielle n’est-elle pas déduite directement de la boîte ?','aclaim':'Parce que les propriétés et traces observables sont compatibles avec plusieurs usages et que les images ou copies ont leurs propres contextes de production.','qamb':'Quelle différence sépare une copie tardive d’un accès direct au premier usage ?','aamb':'La copie renseigne aussi sur l’interprétation de l’époque où elle a été produite et peut modifier ou simplifier des traits du modèle antérieur.','qassume':'Pourquoi faut-il construire plusieurs hypothèses de fonction ?','aassume':'Pour tester si les mêmes indices pourraient être expliqués autrement et identifier les nouvelles preuves réellement discriminantes.','qrhet':'Quel rôle joue la hiérarchie finale des affirmations ?','arhet':'Elle aligne le degré de certitude du langage sur la force des preuves disponibles.','qstance':'Quelle attitude envers les objets historiques est défendue ?','astance':'Les utiliser comme sources riches mais situées, en séparant observation matérielle, relation documentaire et inférence fonctionnelle.'},
{'id':'fr-c2-u08-p04','seq':46,'ptype':'transfer','genre':'historiographical comparison','topics':['shock versus structure','retrospective judgment','actor knowledge'],'title':'Un choc visible n’efface pas les conditions qui le rendent décisif','paras':["Une cité fictive connaît une rupture brutale de son approvisionnement après une tempête. Un récit ultérieur présente la tempête comme cause unique d’une réforme économique majeure. Une seconde étude montre cependant que les réserves diminuaient depuis plusieurs années et que des règles de stockage rendaient certaines zones plus vulnérables. Le dossier compare explication par choc et explication par structure sans nier l’importance de l’événement soudain.","La première tâche consiste à préciser le mécanisme : la tempête réduit les arrivées, ce qui expose les réserves faibles et modifie les décisions. Le choc est réel, mais son effet dépend des conditions préexistantes.","Les sources contemporaines utilisent parfois un langage de pari : les responsables acceptent un risque en supposant que la saison suivante sera normale. Il serait trompeur de juger ce choix uniquement à partir du résultat connu plus tard. La révision de l’unité précédente rappelle qu’une préférence critique doit distinguer effet observé et intention attribuée.","Un autre récit évoque une humeur générale de panique. Le dossier demande de désagréger cette formule : quels quartiers, quels acteurs, quelles dates, quelles déclarations ? La réputation d’un responsable peut aussi colorer les mémoires rédigées après la crise. Affirmer qu’il a réellement anticipé ou ignoré un danger demande donc des sources plus proches de la décision.","La conclusion combine les niveaux. Le choc peut être une cause déclenchante, les stocks une condition de vulnérabilité et certaines règles un mécanisme d’amplification. Une bonne explication n’est pas nécessairement celle qui choisit un seul facteur, mais celle qui indique comment les facteurs se combinent et ce qui se serait probablement passé si l’un d’eux avait été différent."],'qclaim':'Pourquoi la tempête n’est-elle pas rejetée comme cause même si des conditions antérieures comptent ?','aclaim':'Parce qu’elle peut être le déclencheur tandis que les réserves et règles préexistantes déterminent l’ampleur de son effet.','qamb':'Quel problème pose l’expression humeur générale ?','aamb':'Elle peut homogénéiser des réactions différentes; il faut identifier groupes, dates et sources avant de parler d’un état collectif.','qassume':'Pourquoi éviter de juger une décision ancienne seulement par son résultat ?','aassume':'Parce que les acteurs ne connaissaient pas encore l’issue et doivent être évalués selon l’information et les options plausibles disponibles au moment du choix.','qrhet':'Quel rôle joue la réputation du responsable ?','arhet':'Elle montre qu’une évaluation sociale ultérieure peut influencer les récits et doit être séparée des preuves contemporaines sur ses connaissances.','qstance':'Quelle forme d’explication causale conclut le passage ?','astance':'Une explication combinant déclencheur, vulnérabilité et mécanisme d’amplification plutôt qu’une cause unique choisie pour sa visibilité.'},
{'id':'fr-c2-u08-p05','seq':47,'ptype':'integration','genre':'synthesis','topics':['comparative method','temporal sequence','scope'],'title':'Une synthèse forte indique aussi ce qu’elle ne peut pas conclure','paras':["Trois études fictives décrivent des réformes de transport dans des villes imaginaires. Toutes observent une baisse du temps moyen de déplacement après une nouvelle organisation. Les mécanismes proposés diffèrent : répartition des horaires, changement d’itinéraires ou diminution d’un goulot d’étranglement. La synthèse doit identifier ce qui est commun sans transformer la ressemblance du résultat en causalité identique.","Une première approche construit un tableau de comparaison : chronologie, acteurs, contraintes, indicateurs et sources. Le facteur commun devient une question à tester plutôt qu’une réponse présupposée.","Dans un cas, un rapport signale un changement déjà commencé précédemment; dans un autre, l’effet apparaît seulement durant le mois suivant la réforme. L’ordre des événements limite certaines hypothèses mais n’établit pas à lui seul le mécanisme. La révision de l’unité précédente rappelle qu’un échange entre contextes ne produit pas automatiquement une signification partagée.","La synthèse examine ensuite les différences qui pourraient modifier le résultat : taille du réseau, horaires de travail, mesure du temps et comportements d’adaptation. Une comparaison utile peut conclure que la réforme est associée à une amélioration dans les trois cas tout en restant prudente sur la voie causale précise.","La dernière section énonce trois niveaux : constat commun, mécanismes plausibles, inconnues restantes. Elle indique aussi quelles observations futures permettraient de distinguer les hypothèses. La valeur d’une synthèse ne vient donc pas de la suppression des désaccords, mais de l’organisation transparente de ce qui est partagé, contesté et encore ouvert."],'qclaim':'Pourquoi un résultat commun aux trois villes ne prouve-t-il pas un mécanisme causal commun ?','aclaim':'Parce que des contraintes et voies différentes peuvent produire le même résultat observé; le mécanisme doit être testé séparément.','qamb':'Quel rôle joue la chronologie dans la synthèse ?','aamb':'Elle élimine certaines explications incompatibles avec l’ordre des faits, mais ne transforme pas automatiquement ce qui précède en cause.','qassume':'Pourquoi les différences entre cas doivent-elles être analysées ?','aassume':'Parce qu’elles peuvent expliquer pourquoi un même facteur apparent produit des effets différents ou par des voies différentes.','qrhet':'Pourquoi la synthèse énonce-t-elle explicitement les inconnues ?','arhet':'Pour empêcher que l’accord sur certains constats soit interprété comme une certitude sur tous les mécanismes.','qstance':'Quelle conception de la synthèse historique est défendue ?','astance':'Organiser les convergences, désaccords et conditions de révision avec des degrés de confiance explicites.'}]

def checkpoint(groups,D,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]]
 ps=["Le checkpoint rassemble cinq mini-dossiers fictifs : une chaîne de documents dépendants, deux récits causaux d’un même revers, un objet matériel, une crise avec choc et vulnérabilité, puis trois cas comparatifs. Le lecteur doit produire une synthèse qui sépare ce qui est directement observé, ce qui est reconstruit et ce qui reste contesté.","La première tâche reconstruit la provenance et la chronologie. Révision cumulative : "+'; '.join(f'« {f} »' for f in forms)+". Chaque forme sert à nommer une opération précise : dater, qualifier une source, distinguer trace et interprétation, comparer des mécanismes ou annoncer une limite.","La deuxième tâche classe les affirmations selon leur force. Une date peut être confirmée par plusieurs pièces, une relation causale peut être probable, une intention peut rester inconnue. Le lecteur justifie chaque niveau et cherche les dépendances cachées entre sources avant de compter les confirmations.","La troisième tâche construit un scénario rival. Pour chaque explication principale, il propose un mécanisme alternatif compatible avec au moins une partie des données, puis identifie l’observation qui départagerait le mieux les deux. Cette méthode évite de transformer la première histoire cohérente en conclusion nécessaire.","La conclusion impose une règle de rétrospection. Les acteurs sont replacés devant les informations et options disponibles à leur moment; les analystes, eux, doivent utiliser les résultats ultérieurs sans les projeter artificiellement dans les intentions anciennes. Une synthèse réussie peut donc être précise tout en conservant plusieurs zones d’incertitude."]
 ps,text=fit(ps,lo,hi); P=base.prior(prior); rev=[base.rev(f,P) for f in forms]; ids={t['form']:t['id'] for t in rev}
 items=[('main_claim','Quelle méthode commune organise les cinq mini-dossiers ?','Séparer provenance, observation, inférence, causalité et degré de confiance avant de produire la synthèse.',[forms[0]]),('ambiguity_resolution','Pourquoi plusieurs documents ne sont-ils pas automatiquement plusieurs confirmations ?','Ils peuvent dépendre d’une même source ou se recopier, ce qui exige de reconstruire leur provenance.',[forms[5]]),('assumption','Pourquoi construire un scénario causal rival ?','Pour vérifier si les indices discriminent réellement l’explication principale ou restent compatibles avec une autre.',[forms[10]]),('rhetorical_function','Quel rôle joue la règle de rétrospection ?','Elle empêche d’attribuer aux acteurs la connaissance du résultat futur et distingue jugement ex post et décision sous incertitude.',[forms[15]]),('synthesis','Quelle forme de conclusion est valorisée ?','Une conclusion qui distribue des degrés de confiance, conserve les désaccords non résolus et indique quelles preuves permettraient de réviser l’analyse.',[forms[20]]),('vocabulary_in_context',f'Quel rôle historiographique joue « {forms[4]} » ?',USE[forms[4]],[forms[4]]),('vocabulary_in_context',f'Quel rôle historiographique joue « {forms[9]} » ?',USE[forms[9]],[forms[9]]),('vocabulary_in_context',f'Quel rôle historiographique joue « {forms[14]} » ?',USE[forms[14]],[forms[14]]),('vocabulary_in_context',f'Quel rôle historiographique joue « {forms[19]} » ?',USE[forms[19]],[forms[19]]),('register_style','Pourquoi le checkpoint utilise-t-il des cas fictifs ?','Pour exercer la méthode de l’histoire contestée sans présenter comme faits des affirmations non sourcées sur un événement réel.',[forms[24]])]
 q,a=base.qa(items,ids)
 return {'id':'fr-c2-u08-p06','language':'fr','cefr':'C2','unit':8,'sequence':48,'revision':1,'title':'Checkpoint : écrire une histoire précise sans fabriquer une certitude totale','passage_type':'checkpoint','genre':'synthesis','domains':['educational','public','professional'],'topics':[theme,'cumulative historiography'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c2-u08-p06-g1','role':'integration','description':'integrate temporal ordering, evidential modality and counterfactual qualification'}],'discourse_targets':[{'id':'fr-c2-u08-p06-d1','role':'integration','description':'synthesize provenance, source dependence, material evidence, causal rivalry and calibrated uncertainty'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C2 Unit08 zero-new historiography checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['All historical cases are fictional.']},'paired_text_group':None,'prerequisites':['French C2 Unit08 P01-P05'],'difficulty_notes_internal':'C2 cumulative historiographical comparison and source critique.','reader_tags':['unit_role:checkpoint','generation_batch','french_c2_u08']}

def main():
 raw=C2.read_text(encoding='utf-8'); rows=[json.loads(x) for x in raw.splitlines() if x.strip()]; l=json.loads(LOCK.read_text(encoding='utf-8')); p=json.loads(PLAN.read_text(encoding='utf-8')); s=json.loads(SEL.read_text(encoding='utf-8')); c1=h(C1); c2=h(C2)
 if len(rows)!=42 or l.get('status')!='PASS' or l.get('last_sequence')!=42 or l.get('c1_canonical_blob')!=c1 or l.get('c2_canonical_blob')!=c2: raise AssertionError('C2 Unit08 source mismatch')
 if p.get('status')!='PASS' or p.get('c2_source_blob')!=c2 or s.get('status')!='PASS' or s.get('c2_source_blob')!=c2: raise AssertionError('C2 Unit08 plan/selection stale')
 groups=s['passage_groups']; prev=l['unit07_target_groups']; reviews={k:prev[k] for k in ['p01','p02','p03','p04','p05']}; D=c2base.deck(); lo,hi=s['word_band']; prior=c2base.load(c2base.A1)+c2base.load(c2base.A2)+c2base.load(c2base.B1)+c2base.load(c2base.B2)+c2base.load(c2base.C1)+rows
 unit=[make(x,groups[x['id'][-3:]],reviews[x['id'][-3:]],prior,D,lo,hi,p['theme']) for x in specs()]; unit.append(checkpoint(groups,D,lo,hi,p['theme'],prior+unit)); V=Draft202012Validator(json.loads(SCHEMA.read_text(encoding='utf-8')))
 for x in unit:
  errs=list(V.iter_errors(x))
  if errs: raise AssertionError(f"{x['id']}: schema {[e.message for e in errs[:10]]}")
  if len(x['questions'])!=10 or len(x['answer_key'])!=10: raise AssertionError(f"10Q/A fail {x['id']}")
  if not lo<=x['word_count']<=hi: raise AssertionError(f"word band fail {x['id']}: {x['word_count']}")
 if unit[-1]['new_lexical_targets']: raise AssertionError('Unit08 checkpoint must be zero-new')
 C2.write_text(raw+('' if raw.endswith('\n') else '\n')+'\n'.join(json.dumps(x,ensure_ascii=False,sort_keys=True) for x in unit)+'\n',encoding='utf-8')
 print(json.dumps({'status':'PASS','unit':8,'passages':6,'word_counts':[x['word_count'] for x in unit],'new_targets':[len(x['new_lexical_targets']) for x in unit]},ensure_ascii=False))
